//! 🌱️ `ToValue`/`FromValue` for [`super::IconName`] — hand-written in this SIBLING file rather
//! than added to `icon_name_gen`'s source, because that generated file
//! (`🧰️framework/🔨️modules/🖼️assets/🔣️icons/🤖️generated/🦀️icon_name.rs`) is marked
//! `// Generated by asset/script.ts — do not edit.` at its own top line. `IconName` is still LOCAL
//! to this crate (path-mounted via `#[path]` in the wgpu target root `🦀️.rs`, not a foreign-crate
//! type), so the orphan rule is satisfied without touching the generated file.
//!
//! Bridges through the type's EXISTING `serde::Serialize`/`Deserialize` impl (kebab-case
//! `#[serde(rename = "...")]` per variant, ~2300 lines of generated match arms) rather than
//! hand-writing a ~2000-arm match here: `serde_json::to_value`/`from_value` round-trips through
//! the identical wire string the generated `Serialize`/`Deserialize` already produces/accepts, and
//! `DslValue`'s own `From<&serde_json::Value>`/`From<&DslValue> for serde_json::Value` bridge
//! (`🌱️value/🦀️.rs`) carries that JSON string through unchanged — so the wire shape is
//! byte-identical to today's serde encoding, no migration/regeneration needed. Same technique as
//! `MeshData`'s hand-written `ToValue`/`FromValue` in `🏗️mesh-engine/🦀️.rs`, which also avoids the
//! derive because that crate sits below `os-kernel` in the dependency graph — here the reason is
//! narrower (a single "do not edit" file), so only these two impls are hand-written, not the
//! whole `IconName` enum.
//!
//! Ticket 26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS.

use super::IconName;

impl dsl::ToValue for IconName {
    fn to_value(&self) -> dsl::DslValue {
        let json = serde_json::to_value(self).expect("IconName's generated Serialize impl never fails");
        dsl::DslValue::from(&json)
    }
}

impl dsl::FromValue for IconName {
    fn from_value(value: dsl::DslValue) -> Result<Self, dsl::ValueError> {
        let json = serde_json::Value::from(value);
        serde_json::from_value(json).map_err(|error| dsl::ValueError::new(error.to_string()))
    }
}

#[cfg(test)]
mod icon_name_value_round_trip_tests {
    use super::*;
    use dsl::{FromValue, ToValue};

    #[semio_framework_async_macros::async_test]
    async fn round_trips_through_to_value_and_from_value() {
        for icon in [IconName::AlertCircle, IconName::AppWindow, IconName::Lock, IconName::CircleDot, IconName::Sparkles, IconName::Folder] {
            let decoded = IconName::from_value(icon.to_value()).expect("valid DslValue decodes");
            assert_eq!(decoded, icon);
        }
    }

    #[semio_framework_async_macros::async_test]
    async fn to_value_matches_the_existing_serde_wire_string() {
        let icon = IconName::AlertCircle;
        assert_eq!(icon.to_value(), dsl::DslValue::String("alert-circle".to_string()));
    }
}
